window.CIVIL_SET_DATA["past-16"] = {"title":"Past Paper Set 16","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-16-001","src":"PAST-16-001","text":"The commonly used cement for paint is","options":[{"key":"a","text":"White cement"},{"key":"b","text":"Portland cement"},{"key":"c","text":"Alumina cement"},{"key":"d","text":"Rapid hardening cement"}],"answer":"a","explanation":"White cement (low in iron oxide) is the base of cement paints and decorative finishes, since pigments show their true colour in it.","marks":1,"source":{"kind":"past","set":16,"question":1,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q1 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-16-004","src":"PAST-16-004","text":"The centre of gravity of a trapezium with parallel sides 'a' and 'b' lies at a distance 'y' from the base 'b' and has height 'h'. The value of 'y' is","options":[{"key":"a","text":"h(2a+b)/(a+b)"},{"key":"b","text":"(h/2)(2a+b)/(a+b)"},{"key":"c","text":"(h/3)(2a+b)/(a+b)"},{"key":"d","text":"h(a+b)/(2a+b)"}],"answer":"c","explanation":"Measured from the side b, ȳ = (h/3)(2a + b)/(a + b).","marks":1,"source":{"kind":"past","set":16,"question":4,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q4 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-16-010","src":"PAST-16-010","text":"The building material made from rock is","options":[{"key":"a","text":"Brick"},{"key":"b","text":"Stone"},{"key":"c","text":"Cement"},{"key":"d","text":"All of these"}],"answer":"b","explanation":"Building stone is quarried and dressed directly from natural rock. Bricks are burnt clay and cement is a manufactured product.","marks":1,"source":{"kind":"past","set":16,"question":10,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q10 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-16-028","src":"PAST-16-028","text":"What quantity of binding wire is required for fixing one quintal of steel bars?","options":[{"key":"a","text":"12 kg"},{"key":"b","text":"5 kg"},{"key":"c","text":"10 kg"},{"key":"d","text":"1 kg"}],"answer":"d","explanation":"About 1 kg of binding wire is allowed per quintal (100 kg) of reinforcement.","marks":1,"source":{"kind":"past","set":16,"question":28,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q28 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-16-029","src":"PAST-16-029","text":"Which among the following is not a type of non-destructive testing?","options":[{"key":"a","text":"Eddy current testing"},{"key":"b","text":"Visual testing"},{"key":"c","text":"Ultrasonic testing"},{"key":"d","text":"Compression test"}],"answer":"d","explanation":"A compression test crushes the specimen, so it is destructive. Visual, ultrasonic and eddy-current inspections leave the member intact.","marks":1,"source":{"kind":"past","set":16,"question":29,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q29 · 1 mark"},"topic":"ACiE0102"},{"id":"PAST-16-034","src":"PAST-16-034","text":"The rarely found rock in Nepal is","options":[{"key":"a","text":"Granite"},{"key":"b","text":"Basalt"},{"key":"c","text":"Sandstone"},{"key":"d","text":"Limestone"}],"answer":"b","explanation":"Nepal's rocks are mainly sedimentary and metamorphic (limestone, sandstone, phyllite, quartzite) with some granite. Volcanic basalt is rare.","marks":1,"source":{"kind":"past","set":16,"question":34,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q34 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-16-041","src":"PAST-16-041","text":"The percentage of magnesia in cement is","options":[{"key":"a","text":"3-5"},{"key":"b","text":"1-3"},{"key":"c","text":"4-6"},{"key":"d","text":"none of these"}],"answer":"b","explanation":"OPC typically contains about 1–3% MgO (magnesia). The code limit is 6%, since excess magnesia causes unsoundness.","marks":1,"source":{"kind":"past","set":16,"question":41,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q41 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-16-063","src":"PAST-16-063","text":"Which of the following is not a type of non-destructive test?","options":[{"key":"a","text":"Compression test"},{"key":"b","text":"Visual testing"},{"key":"c","text":"Ultrasonic testing"},{"key":"d","text":"Eddy current testing"}],"answer":"a","explanation":"A compression test crushes the specimen, so it is destructive. The others inspect without damage.","marks":2,"source":{"kind":"past","set":16,"question":63,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q63 · 2 marks"},"topic":"ACiE0102"},{"id":"PAST-16-074","src":"PAST-16-074","text":"An L-section has a vertical leg 20 mm wide and 120 mm high and a horizontal leg 60 mm long and 20 mm thick attached at its foot (total width 80 mm). Find its CG (x̄, ȳ) from the outer corner.","options":[{"key":"a","text":"(23.3, 43.3)"},{"key":"b","text":"(33.3, 43.3)"},{"key":"c","text":"(43.3, 23.3)"},{"key":"d","text":"(23.3, 33.3)"}],"answer":"a","explanation":"The two parts are \\(A_1 = 2400\\) mm<sup>2</sup> at (10, 60) and \\(A_2 = 1200\\) mm<sup>2</sup> at (50, 10), so \\[\\bar x = \\dfrac{24{,}000 + 60{,}000}{3600} \\approx 23.3\\] \\[\\bar y = \\dfrac{144{,}000 + 12{,}000}{3600} \\approx 43.3\\] (The paper shows the section as a figure; its dimensions are taken from the key's working.)","marks":2,"source":{"kind":"past","set":16,"question":74,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q74 · 2 marks"},"topic":"ACiE0104"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-16-016","src":"PAST-16-016","text":"The unconfined compressive test is carried out on","options":[{"key":"a","text":"silt"},{"key":"b","text":"sand"},{"key":"c","text":"clay"},{"key":"d","text":"gravel"}],"answer":"c","explanation":"The unconfined compression test needs a cohesive specimen that stands without lateral support, i.e. saturated clay with \\(\\phi_u \\approx 0\\). Then \\[c_u = \\dfrac{q_u}{2}\\]","marks":1,"source":{"kind":"past","set":16,"question":16,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q16 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-16-018","src":"PAST-16-018","text":"No tension should develop at the base of a rectangular well foundation or at any horizontal section within the well. For no tension at the base, the resultant of P (total active thrust) and W (weight of soil and well above the base) must pass through the middle","options":[{"key":"a","text":"half of the base"},{"key":"b","text":"of the base"},{"key":"c","text":"quarter of the base"},{"key":"d","text":"third of the base"}],"answer":"d","explanation":"For a rectangular section, no tension develops while the resultant stays within the middle third (e ≤ b/6).","marks":1,"source":{"kind":"past","set":16,"question":18,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q18 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-16-021","src":"PAST-16-021","text":"The most appropriate triaxial test to assess the long-term stability of an excavated clay slope is","options":[{"key":"a","text":"unconfined compression test"},{"key":"b","text":"consolidated drained test"},{"key":"c","text":"unconsolidated undrained test"},{"key":"d","text":"consolidated undrained test"}],"answer":"b","explanation":"In the long term the excess pore pressures from excavation dissipate, so the drained strength (c′, φ′) governs. The CD test measures it.","marks":1,"source":{"kind":"past","set":16,"question":21,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q21 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-16-033","src":"PAST-16-033","text":"The effect of surcharge pressure on effective pressure is","options":[{"key":"a","text":"effective stress increases by the surcharge load"},{"key":"b","text":"effective stress decreases by the surcharge load"},{"key":"c","text":"remains constant"},{"key":"d","text":"None of these"}],"answer":"a","explanation":"A surcharge raises the total stress. Once the excess pore pressure dissipates (drained, long term), the effective stress rises by the full surcharge.","marks":1,"source":{"kind":"past","set":16,"question":33,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q33 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-16-042","src":"PAST-16-042","text":"The bearing capacity of cohesionless soil from a plate load test is","options":[{"key":"a","text":"\\(q_{u(p)}\\)"},{"key":"b","text":"\\(\\dfrac{B_p}{B_f} \\times q_{u(p)}\\)"},{"key":"c","text":"\\(2q_{u(p)}\\)"},{"key":"d","text":"\\(\\dfrac{B_f}{B_p} \\times q_{u(p)}\\)"}],"answer":"d","explanation":"For sands the ultimate bearing capacity grows with width: \\[q_{u(f)} = q_{u(p)}\\dfrac{B_f}{B_p}\\] For clays it is the same as the plate value.","marks":1,"source":{"kind":"past","set":16,"question":42,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q42 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-16-076","src":"PAST-16-076","text":"Which of the following cannot be obtained by using an undrained test?","options":[{"key":"a","text":"Effective stress failure envelope"},{"key":"b","text":"Shear strength"},{"key":"c","text":"Sensitivity"},{"key":"d","text":"All of the mentioned"}],"answer":"a","explanation":"An undrained test without pore-pressure measurement gives only total-stress parameters (c<sub>u</sub>), from which sensitivity can be found. The effective-stress envelope needs drained tests or measured pore pressures.","marks":2,"source":{"kind":"past","set":16,"question":76,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q76 · 2 marks"},"topic":"ACiE0203"},{"id":"PAST-16-077","src":"PAST-16-077","text":"In geotechnical engineering, a vane shear test is typically conducted to determine the shear strength of which of the following soil types?","options":[{"key":"a","text":"Soft clays"},{"key":"b","text":"Coarse sand"},{"key":"c","text":"Shingle"},{"key":"d","text":"Gravel"}],"answer":"a","explanation":"The vane test measures the undrained shear strength (and sensitivity) of soft to firm saturated clays in the field, where good samples are hard to obtain.","marks":2,"source":{"kind":"past","set":16,"question":77,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q77 · 2 marks"},"topic":"ACiE0204"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-16-002","src":"PAST-16-002","text":"If your weight on earth is W kg, what will be your weight on the moon?","options":[{"key":"a","text":"W kg"},{"key":"b","text":"3W kg"},{"key":"c","text":"W/6 kg"},{"key":"d","text":"W/3 kg"}],"answer":"c","explanation":"Gravity on the moon is about one-sixth of Earth's, so weight (mg) becomes W/6. Strictly, mass in kg stays the same; the question uses 'kg' loosely for weight.","marks":1,"source":{"kind":"past","set":16,"question":2,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q2 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-16-008","src":"PAST-16-008","text":"In what direction does the buoyant force on an object immersed in a liquid act?","options":[{"key":"a","text":"Vertically downward direction"},{"key":"b","text":"Vertically upward direction"},{"key":"c","text":"Towards centre"},{"key":"d","text":"Anywhere"}],"answer":"b","explanation":"The buoyant force acts vertically upward through the centre of buoyancy and equals the weight of liquid displaced.","marks":1,"source":{"kind":"past","set":16,"question":8,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q8 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-16-014","src":"PAST-16-014","text":"The relation between Manning's \\(n\\) and Chezy's \\(C\\) is given by (where \\(R\\) = hydraulic mean depth)","options":[{"key":"a","text":"\\(\\dfrac{R^{1/6}}{n}\\)"},{"key":"b","text":"\\(\\dfrac{R^{2/3}}{n}\\)"},{"key":"c","text":"\\(\\dfrac{R^{1/3}}{n}\\)"},{"key":"d","text":"\\(\\dfrac{R^{1/3}}{n^2}\\)"}],"answer":"a","explanation":"Equating Chezy \\(V = C\\sqrt{RS}\\) with Manning \\[V = \\dfrac{1}{n}R^{2{/}3}S^{1{/}2}\\] gives \\[C = \\dfrac{R^{1{/}6}}{n}\\]","marks":1,"source":{"kind":"past","set":16,"question":14,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q14 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-16-019","src":"PAST-16-019","text":"In a two-dimensional flow, the components of velocity along the X-axis and the Y-axis are \\(u = ax^2 + bxy\\) and \\(v = cxy + dy^2\\). What should be the condition for the flow field to be continuous?","options":[{"key":"a","text":"\\((a+b)x\\) \\(+\\,(c+d)y = 0\\)"},{"key":"b","text":"\\((a+c)x\\) \\(+\\,(b+d)y = 0\\)"},{"key":"c","text":"\\((2a+b)x\\) \\(+\\,(c+2d)y = 0\\)"},{"key":"d","text":"\\((2a+c)x\\) \\(+\\,(b+2d)y = 0\\)"}],"answer":"d","explanation":"Continuity requires \\(\\dfrac{\\partial u}{\\partial x} + \\dfrac{\\partial v}{\\partial y} = 0\\): \\[(2ax + by) + (cx + 2dy) = 0\\] \\[(2a + c)x + (b + 2d)y = 0\\]","marks":1,"source":{"kind":"past","set":16,"question":19,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q19 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-16-038","src":"PAST-16-038","text":"In a venturi meter, the velocity of liquid at the throat is …… than at the inlet.","options":[{"key":"a","text":"higher"},{"key":"b","text":"lower"},{"key":"c","text":"remains same"},{"key":"d","text":"all of these"}],"answer":"a","explanation":"By continuity \\(AV = \\text{constant}\\), so the smaller throat area gives a higher velocity (and lower pressure, which is what the meter measures).","marks":1,"source":{"kind":"past","set":16,"question":38,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q38 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-16-039","src":"PAST-16-039","text":"When pipes are connected in series, then","options":[{"key":"a","text":"pressure will be low"},{"key":"b","text":"discharge will be more"},{"key":"c","text":"pressure will be medium"},{"key":"d","text":"discharge will be constant"}],"answer":"d","explanation":"In series the same discharge passes through each pipe, and the total head loss is the sum of the individual losses.","marks":1,"source":{"kind":"past","set":16,"question":39,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q39 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-16-048","src":"PAST-16-048","text":"The branch of science which deals with the occurrence, circulation and distribution of the waters of the earth and its atmosphere is","options":[{"key":"a","text":"Precipitation"},{"key":"b","text":"Climatology"},{"key":"c","text":"Hydrology"},{"key":"d","text":"Meteorology"}],"answer":"c","explanation":"Hydrology is the science of the occurrence, circulation (the hydrologic cycle) and distribution of water on and below the earth and in the atmosphere.","marks":1,"source":{"kind":"past","set":16,"question":48,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q48 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-16-058","src":"PAST-16-058","text":"A mild-sloped channel is followed by a steep-sloped channel. The profiles of gradually varied flow in the channel are","options":[{"key":"a","text":"M3, S2"},{"key":"b","text":"M3, S3"},{"key":"c","text":"M2, S1"},{"key":"d","text":"M2, S2"}],"answer":"d","explanation":"The flow passes through critical depth at the break in slope. Upstream it draws down as an M2 curve, and downstream it falls towards the steep normal depth as an S2 curve.","marks":1,"source":{"kind":"past","set":16,"question":58,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q58 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-16-064","src":"PAST-16-064","text":"As per the topography of Nepal, rivers are classified into …. groups","options":[{"key":"a","text":"2"},{"key":"b","text":"3"},{"key":"c","text":"4"},{"key":"d","text":"5"}],"answer":"b","explanation":"Nepal's rivers fall into three groups: major snow-fed rivers (Koshi, Gandaki, Karnali, Mahakali), medium rivers from the Mahabharat range, and small seasonal (Siwalik/Terai) rivers.","marks":2,"source":{"kind":"past","set":16,"question":64,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q64 · 2 marks"},"topic":"ACiE0306"},{"id":"PAST-16-071","src":"PAST-16-071","text":"In a venturi meter, which portion typically has the highest velocity?","options":[{"key":"a","text":"Inlet"},{"key":"b","text":"Throat"},{"key":"c","text":"Outlet"},{"key":"d","text":"None of the above"}],"answer":"b","explanation":"The throat has the smallest area, so by continuity it has the highest velocity and the lowest pressure.","marks":2,"source":{"kind":"past","set":16,"question":71,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q71 · 2 marks"},"topic":"ACiE0303"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-16-032","src":"PAST-16-032","text":"Hooke's law holds good up to","options":[{"key":"a","text":"Yield point"},{"key":"b","text":"Limit of proportionality"},{"key":"c","text":"Breaking point"},{"key":"d","text":"Elastic limit"}],"answer":"b","explanation":"Stress is directly proportional to strain only up to the limit of proportionality. The elastic limit may lie slightly beyond it.","marks":1,"source":{"kind":"past","set":16,"question":32,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q32 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-16-043","src":"PAST-16-043","text":"For a simply supported beam, the bending moment diagram due to a point load is","options":[{"key":"a","text":"Rectangular"},{"key":"b","text":"Square"},{"key":"c","text":"Triangular"},{"key":"d","text":"Line"}],"answer":"c","explanation":"The BM varies linearly from zero at each support to Wab/L under the load, forming a triangle.","marks":1,"source":{"kind":"past","set":16,"question":43,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q43 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-16-052","src":"PAST-16-052","text":"The formula to calculate the maximum normal stress is","options":[{"key":"a","text":"\\(\\dfrac{\\sigma_x}{2} + \\dfrac{1}{2}\\sqrt{\\sigma_x^2 + 4\\tau_{xy}^2}\\)"},{"key":"b","text":"\\(\\dfrac{\\sigma_x}{2} + \\dfrac{1}{2}\\sqrt{\\sigma_x^2 + \\tau_{xy}^2}\\)"},{"key":"c","text":"\\(\\dfrac{\\sigma_x}{2} + \\dfrac{1}{2}\\sqrt{\\sigma_x^2 + 2\\tau_{xy}^2}\\)"},{"key":"d","text":"\\(\\dfrac{\\sigma_x}{2} + \\dfrac{1}{2}\\sqrt{\\sigma_x^2 - \\tau_{xy}^2}\\)"}],"answer":"a","explanation":"With a single normal stress \\(\\sigma_x\\) and shear \\(\\tau\\), \\[\\sigma_{max} = \\dfrac{\\sigma_x}{2} + \\sqrt{\\left(\\dfrac{\\sigma_x}{2}\\right)^2 + \\tau^2}\\] \\[= \\dfrac{\\sigma_x}{2} + \\dfrac{1}{2}\\sqrt{\\sigma_x^2 + 4\\tau^2}\\]","marks":1,"source":{"kind":"past","set":16,"question":52,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q52 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-16-053","src":"PAST-16-053","text":"Select the correct formula for the horizontal thrust (of a two-hinged arch) when there is a temperature increase (\\(T\\)) and the effect of rib shortening is considered.","options":[{"key":"a","text":"\\(\\dfrac{\\int\\! My\\,ds/EI + L\\alpha T}{\\int\\! y^2 ds/EI + \\int\\! ds/AE}\\)"},{"key":"b","text":"\\(\\dfrac{\\int\\! My\\,ds/EI + L\\alpha T}{\\int\\! y^2 ds/EI - \\int\\! ds/AE}\\)"},{"key":"c","text":"\\(\\dfrac{\\int\\! My\\,ds/EI - L\\alpha T}{\\int\\! y^2 ds/EI + \\int\\! ds/AE}\\)"},{"key":"d","text":"\\(\\dfrac{\\int\\! My\\,ds/EI - L\\alpha T}{\\int\\! y^2 ds/EI - \\int\\! ds/AE}\\)"}],"answer":"a","explanation":"A temperature rise tries to spread the supports by LαT, increasing the thrust, so it adds to the numerator. Rib shortening adds a flexibility term to the denominator, reducing the thrust.","marks":1,"source":{"kind":"past","set":16,"question":53,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q53 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-16-055","src":"PAST-16-055","text":"A two hinged parabolic arch carrying UDL throughout the span has a BM of","options":[{"key":"a","text":"\\(\\dfrac{wl^2}{8}\\)"},{"key":"b","text":"\\(\\dfrac{wl^2}{10}\\)"},{"key":"c","text":"\\(\\dfrac{wl^2}{12}\\)"},{"key":"d","text":"zero"}],"answer":"d","explanation":"Under full-span UDL, \\[H = \\dfrac{wl^2}{8h}\\] makes the line of thrust coincide with the parabolic axis, so the bending moment is zero everywhere (pure compression).","marks":1,"source":{"kind":"past","set":16,"question":55,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q55 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-16-075","src":"PAST-16-075","text":"The stiffness of a member if the farther end is hinged is","options":[{"key":"a","text":"\\(0\\)"},{"key":"b","text":"\\(\\dfrac{EI}{L}\\)"},{"key":"c","text":"\\(\\dfrac{3EI}{L}\\)"},{"key":"d","text":"\\(\\dfrac{4EI}{L}\\)"}],"answer":"c","explanation":"With the far end pinned, rotating the near end through a unit angle needs 3EI/L. It is 4EI/L when the far end is fixed.","marks":2,"source":{"kind":"past","set":16,"question":75,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q75 · 2 marks"},"topic":"ACiE0406"},{"id":"PAST-16-078","src":"PAST-16-078","text":"The ratio of maximum deflection due to UDL throughout the span for a fixed beam and a simply supported beam of similar dimensions is","options":[{"key":"a","text":"1:3"},{"key":"b","text":"3:1"},{"key":"c","text":"1:5"},{"key":"d","text":"5:1"}],"answer":"c","explanation":"The two central deflections are \\[\\delta_{fixed} = \\dfrac{wL^4}{384EI}\\] \\[\\delta_{ss} = \\dfrac{5wL^4}{384EI}\\] so the ratio is 1:5.","marks":2,"source":{"kind":"past","set":16,"question":78,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q78 · 2 marks"},"topic":"ACiE0406"},{"id":"PAST-16-080","src":"PAST-16-080","text":"A beam simply supported over a 4 m span with a 2 m overhang carries a UDL of 10 kN/m over its whole length. Calculate the maximum negative BM.","options":[{"key":"a","text":"10 kNm"},{"key":"b","text":"40 kN"},{"key":"c","text":"30 kNm"},{"key":"d","text":"20 kNm"}],"answer":"d","explanation":"The maximum hogging moment occurs at the support next to the overhang: \\[\\dfrac{wa^2}{2} = \\dfrac{10 \\times 2^2}{2} = 20\\ \\text{kNm}\\] (The paper gives the beam as a figure; its data come from the key's working.)","marks":2,"source":{"kind":"past","set":16,"question":80,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q80 · 2 marks"},"topic":"ACiE0401"}]},{"name":"Design of Structures","questions":[{"id":"PAST-16-005","src":"PAST-16-005","text":"The design for load bearing masonry is based upon","options":[{"key":"a","text":"NBC 201"},{"key":"b","text":"NBC 202"},{"key":"c","text":"NBC 203"},{"key":"d","text":"NBC 205"}],"answer":"b","explanation":"NBC 202 gives the mandatory rules of thumb for load-bearing masonry buildings. NBC 201 covers RC frames with masonry infill, and NBC 203 and 205 cover low-strength and RC buildings without design.","marks":1,"source":{"kind":"past","set":16,"question":5,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q5 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-16-017","src":"PAST-16-017","text":"The minimum clear cover for a column is","options":[{"key":"a","text":"25 mm"},{"key":"b","text":"40 mm"},{"key":"c","text":"50 mm"},{"key":"d","text":"75 mm"}],"answer":"a","explanation":"IS 456 requires 40 mm nominal cover to column longitudinal bars. For columns whose smaller dimension is 200 mm or less, with bars up to 12 mm, it allows 25 mm, and the key takes this lower limit.","marks":1,"source":{"kind":"past","set":16,"question":17,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q17 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-16-037","src":"PAST-16-037","text":"A circular column section is generally not used in actual practice because","options":[{"key":"a","text":"it is uneconomical"},{"key":"b","text":"it cannot carry the load safely"},{"key":"c","text":"it is difficult to connect beams to the round sections"},{"key":"d","text":"all of the above"}],"answer":"c","explanation":"Rectangular beams frame awkwardly into round columns, which complicates formwork and joint detailing. Circular columns are otherwise efficient.","marks":1,"source":{"kind":"past","set":16,"question":37,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q37 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-16-045","src":"PAST-16-045","text":"Which of the following IS standard codes specifies live or imposed loads?","options":[{"key":"a","text":"IS 456: 2"},{"key":"b","text":"IS 456: 3"},{"key":"c","text":"IS 875: 3"},{"key":"d","text":"IS 875: 2"}],"answer":"d","explanation":"IS 875 Part 2 gives imposed (live) loads, and Part 3 gives wind loads. IS 456 is the concrete code.","marks":1,"source":{"kind":"past","set":16,"question":45,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q45 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-16-050","src":"PAST-16-050","text":"The average anchorage value of hooks is","options":[{"key":"a","text":"16 dia"},{"key":"b","text":"20 dia"},{"key":"c","text":"32 dia"},{"key":"d","text":"12 dia"}],"answer":"a","explanation":"A standard hook (180° U-bend) is credited with an anchorage value of 16φ. A 90° bend is worth 8φ.","marks":1,"source":{"kind":"past","set":16,"question":50,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q50 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-16-057","src":"PAST-16-057","text":"The number of zones of soil classification in the Nepal seismic code is","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"4"},{"key":"d","text":"5"}],"answer":"c","explanation":"NBC 105:2020 classifies sites into four soil types (A: rock or stiff, B: medium, C: soft, D: very soft), each with its own spectral shape.","marks":1,"source":{"kind":"past","set":16,"question":57,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q57 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-16-059","src":"PAST-16-059","text":"In reinforcement, what does the symbol \\(\\phi\\) denote?","options":[{"key":"a","text":"Radius"},{"key":"b","text":"Circumference"},{"key":"c","text":"Area"},{"key":"d","text":"Diameter"}],"answer":"d","explanation":"In reinforcement notation, φ (or Ø) denotes the bar diameter, for example 12φ at 150 c/c.","marks":1,"source":{"kind":"past","set":16,"question":59,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q59 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-16-062","src":"PAST-16-062","text":"In the compressive strength test, the minimum strength developed by a cube of M20 cement concrete in 7 days is","options":[{"key":"a","text":"10 MPa"},{"key":"b","text":"20 MPa"},{"key":"c","text":"15 MPa"},{"key":"d","text":"13 MPa"}],"answer":"d","explanation":"At 7 days OPC concrete reaches about 65-67% of its 28-day strength: \\[0.65 \\times 20 \\approx 13\\ \\text{MPa}\\]","marks":2,"source":{"kind":"past","set":16,"question":62,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q62 · 2 marks"},"topic":"ACiE0502"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-16-003","src":"PAST-16-003","text":"The number of goals of sustainable development is","options":[{"key":"a","text":"15"},{"key":"b","text":"17"},{"key":"c","text":"19"},{"key":"d","text":"21"}],"answer":"b","explanation":"The UN 2030 Agenda (2015) has 17 Sustainable Development Goals with 169 targets.","marks":1,"source":{"kind":"past","set":16,"question":3,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q3 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-16-007","src":"PAST-16-007","text":"When bleaching powder is added to water, its pH value","options":[{"key":"a","text":"decreases"},{"key":"b","text":"increases"},{"key":"c","text":"remains unaffected"},{"key":"d","text":"depends on the characteristics of water"}],"answer":"b","explanation":"Bleaching powder (calcium hypochlorite) gives alkaline products (\\(\\text{OCl}^-\\) and Ca(OH)<sub>2</sub>), so the pH rises.","marks":1,"source":{"kind":"past","set":16,"question":7,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q7 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-16-009","src":"PAST-16-009","text":"Which of the following is called an inverted siphon?","options":[{"key":"a","text":"Lateral sewer"},{"key":"b","text":"Outfall sewer"},{"key":"c","text":"Depressed sewer"},{"key":"d","text":"Main sewer"}],"answer":"c","explanation":"An inverted siphon is a depressed sewer that dips below an obstruction (river, valley, road) and flows full under pressure.","marks":1,"source":{"kind":"past","set":16,"question":9,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q9 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-16-024","src":"PAST-16-024","text":"The minimum diameter of sewer generally adopted during design is","options":[{"key":"a","text":"100 mm"},{"key":"b","text":"150 mm"},{"key":"c","text":"200 mm"},{"key":"d","text":"300 mm"}],"answer":"b","explanation":"Public sewers are generally at least 150 mm in diameter to prevent blockage. House connections may be 100 mm.","marks":1,"source":{"kind":"past","set":16,"question":24,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q24 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-16-046","src":"PAST-16-046","text":"Chlorine usage in the treatment of 25000 m<sup>3</sup>/day is 9 kg/day. The residual chlorine after 10 min of contact is 0.2 mg/l. Calculate the dosage in milligrams per litre and the chlorine demand of the water.","options":[{"key":"a","text":"0.36 mg/l, 0.16 mg/l"},{"key":"b","text":"0.36 mg/l, 0.36 mg/l"},{"key":"c","text":"0.16 mg/l, 0.36 mg/l"},{"key":"d","text":"0.16 mg/l, 0.16 mg/l"}],"answer":"a","explanation":"The dose is \\[\\dfrac{9 \\times 10^6\\ \\text{mg}}{25 \\times 10^6\\ \\text{L}} = 0.36\\ \\text{mg/L}\\] The demand is the dose minus the residual: \\[0.36 - 0.2 = 0.16\\ \\text{mg/L}\\]","marks":1,"source":{"kind":"past","set":16,"question":46,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q46 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-16-066","src":"PAST-16-066","text":"The oxygen sag curve was developed by","options":[{"key":"a","text":"Camp's method"},{"key":"b","text":"Darcy-Weisbach method"},{"key":"c","text":"Henry's method"},{"key":"d","text":"Streeter Phelps method"}],"answer":"d","explanation":"The Streeter–Phelps equation (1925) describes the DO sag in a stream as deoxygenation by BOD competes with reaeration.","marks":2,"source":{"kind":"past","set":16,"question":66,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q66 · 2 marks"},"topic":"ACiE0605"},{"id":"PAST-16-079","src":"PAST-16-079","text":"What is the full form of BES?","options":[{"key":"a","text":"Brief Environmental Study"},{"key":"b","text":"British Environmental Study"},{"key":"c","text":"British Engineering Study"},{"key":"d","text":"None"}],"answer":"a","explanation":"Under Nepal's Environment Protection Act 2076 and its rules, BES (Brief Environmental Study) is the simplest level of environmental assessment, below IEE and EIA.","marks":2,"source":{"kind":"past","set":16,"question":79,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q79 · 2 marks"},"topic":"ACiE0606"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-16-013","src":"PAST-16-013","text":"Khosla's theory can be used for calculating which of the following?","options":[{"key":"a","text":"Uplift pressure and exit gradient"},{"key":"b","text":"Seepage pressure"},{"key":"c","text":"None of the mentioned"},{"key":"d","text":"All of the mentioned"}],"answer":"a","explanation":"Khosla's method of independent variables gives the residual uplift pressures at key points of the floor, and the exit gradient that governs piping safety.","marks":1,"source":{"kind":"past","set":16,"question":13,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q13 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-16-020","src":"PAST-16-020","text":"Which type of open drains would be fully operative only in the rainy season?","options":[{"key":"a","text":"Shallow surface drains"},{"key":"b","text":"Drains"},{"key":"c","text":"French drains"},{"key":"d","text":"Deep surface drains"}],"answer":"d","explanation":"Deep surface drains carry both shallow surface runoff and seepage water, with a small central cunette for the dry-weather seepage. They run at full section only during the rains.","marks":1,"source":{"kind":"past","set":16,"question":20,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q20 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-16-030","src":"PAST-16-030","text":"Khosla's safe exit gradient for the design of weirs will be the lowest for which of the following soil types?","options":[{"key":"a","text":"Coarse sand"},{"key":"b","text":"Gravels"},{"key":"c","text":"Fine sand"},{"key":"d","text":"Shingles"}],"answer":"c","explanation":"Fine sand is the most easily lifted by upward seepage, so its safe exit gradient is the lowest (about \\(\\dfrac{1}{6}\\) to \\(\\dfrac{1}{7}\\)), compared with \\(\\dfrac{1}{4}\\) to \\(\\dfrac{1}{5}\\) for shingle.","marks":1,"source":{"kind":"past","set":16,"question":30,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q30 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-16-031","src":"PAST-16-031","text":"Kennedy's design consideration for canal design is based upon","options":[{"key":"a","text":"bed is unprotected, side slope is protected"},{"key":"b","text":"bed is protected, side slope is unprotected"},{"key":"c","text":"both bed and side slope are protected"},{"key":"d","text":"both bed and side slope are unprotected"}],"answer":"a","explanation":"Kennedy held that the eddies keeping silt in suspension rise from the bed only, and ignored the sides. The key describes this as an unprotected (active) bed with protected sides.","marks":1,"source":{"kind":"past","set":16,"question":31,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q31 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-16-044","src":"PAST-16-044","text":"How many types of river training works are there?","options":[{"key":"a","text":"2"},{"key":"b","text":"3"},{"key":"c","text":"5"},{"key":"d","text":"7"}],"answer":"b","explanation":"River training is classified into three types: high-water (flood) training, low-water training and mean-water training.","marks":1,"source":{"kind":"past","set":16,"question":44,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q44 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-16-047","src":"PAST-16-047","text":"Determine the shear stress required to move a single grain on the side slopes, if the critical shear stress required to move a similar grain on the horizontal bed is 2.91 N/m<sup>2</sup>. Consider the angle of the side slope with the horizontal as 30° and the angle of repose of soil as 37°.","options":[{"key":"a","text":"1.61 N/m<sup>2</sup>"},{"key":"b","text":"2.61 N/m<sup>2</sup>"},{"key":"c","text":"1.61 N"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"The side-slope critical shear is \\[\\tau_s = \\tau_b\\cos\\theta\\sqrt{1 - \\dfrac{\\tan^2\\theta}{\\tan^2\\phi}}\\] \\[\\begin{aligned} &amp;= 2.91 \\times 0.866 \\\\ &amp;\\quad \\times \\sqrt{1 - \\dfrac{0.333}{0.568}} \\\\ &amp;\\approx 1.61\\ \\text{N/m}^2 \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":16,"question":47,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q47 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-16-072","src":"PAST-16-072","text":"What is the term for the sheet of water flowing over a weir?","options":[{"key":"a","text":"Crest"},{"key":"b","text":"Head"},{"key":"c","text":"Sill"},{"key":"d","text":"Nappe/vein"}],"answer":"d","explanation":"The sheet of water springing over a weir or notch is the nappe (vein). The crest or sill is the edge it flows over, and the head is the depth above the crest.","marks":2,"source":{"kind":"past","set":16,"question":72,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q72 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-16-073","src":"PAST-16-073","text":"What is the Shields diagram used for in sediment transport?","options":[{"key":"a","text":"Estimating sediment volume"},{"key":"b","text":"Predicting incipient motion"},{"key":"c","text":"Calculating the volume of transported sediment"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"The Shields diagram gives the critical dimensionless shear stress against the particle Reynolds number, i.e. the condition at which bed grains begin to move.","marks":2,"source":{"kind":"past","set":16,"question":73,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q73 · 2 marks"},"topic":"ACiE0702"}]},{"name":"Hydropower","questions":[{"id":"PAST-16-015","src":"PAST-16-015","text":"When was Pharping Hydropower established in Nepal?","options":[{"key":"a","text":"1907"},{"key":"b","text":"1919"},{"key":"c","text":"1915"},{"key":"d","text":"1911"}],"answer":"d","explanation":"Pharping (Chandrajyoti) hydropower station, Nepal's first, 500 kW, was commissioned in 1911 AD (1968 BS) under Chandra Shumsher.","marks":1,"source":{"kind":"past","set":16,"question":15,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q15 · 1 mark"},"topic":"ACiE0801"},{"id":"PAST-16-025","src":"PAST-16-025","text":"What is the formula for the velocity of the water jet at the inlet of a Pelton turbine? (\\(H\\) = net head acting on the Pelton wheel, \\(C_v\\) = coefficient of velocity of the jet)","options":[{"key":"a","text":"\\(V = C_v\\sqrt{gH}\\)"},{"key":"b","text":"\\(V = 2C_v g\\sqrt{H}\\)"},{"key":"c","text":"\\(V = 2C_v\\sqrt{2H}\\)"},{"key":"d","text":"\\(V = C_v\\sqrt{2gH}\\)"}],"answer":"d","explanation":"The jet velocity is \\[V = C_v\\sqrt{2gH}\\] with \\(C_v \\approx 0.97\\) to 0.99.","marks":1,"source":{"kind":"past","set":16,"question":25,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q25 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-16-035","src":"PAST-16-035","text":"What is the recommended formula for the top width of a very low (earth) dam?","options":[{"key":"a","text":"H + 3"},{"key":"b","text":"0.2H + 3"},{"key":"c","text":"0.2H"},{"key":"d","text":"H + 5"}],"answer":"b","explanation":"For very low earth dams the top width is commonly taken as \\[b = \\dfrac{H}{5} + 3 = 0.2H + 3\\] in metres.","marks":1,"source":{"kind":"past","set":16,"question":35,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q35 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-16-056","src":"PAST-16-056","text":"If the FOS against overturning is less in a dam, what can be done to increase it?","options":[{"key":"a","text":"Anchorage at bottom"},{"key":"b","text":"Anchorage at top"},{"key":"c","text":"Shear key below foundation"},{"key":"d","text":"Stone pitching"}],"answer":"a","explanation":"Anchoring the base (heel) of the dam into the foundation rock adds a restoring force against overturning, as the key states. Shear keys improve sliding resistance, and stone pitching protects slopes.","marks":1,"source":{"kind":"past","set":16,"question":56,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q56 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-16-060","src":"PAST-16-060","text":"A 2 m diameter sluiceway at RL 300 m is provided through a concrete overflow dam section to release water to the downstream, where the tail water level is not more than 275 m. The discharge through this outlet when the water level in the reservoir is at the FRL of 330 m is of the order of","options":[{"key":"a","text":"20 cumecs"},{"key":"b","text":"40 cumecs"},{"key":"c","text":"50 cumecs"},{"key":"d","text":"80 cumecs"}],"answer":"c","explanation":"The outlet discharges freely, since the tailwater is below it, under \\(H = 330 - 300 = 30\\) m. Then \\[\\begin{aligned} Q &amp;= C_dA\\sqrt{2gH} \\\\ &amp;\\approx 0.65 \\times \\pi \\times 24.3 \\\\ &amp;\\approx 50\\ \\text{m}^3\\text{/s} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":16,"question":60,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q60 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-16-065","src":"PAST-16-065","text":"A surge tank is used to","options":[{"key":"a","text":"store water"},{"key":"b","text":"safely release flood water"},{"key":"c","text":"reduce the pressure swings in the conduit"},{"key":"d","text":"feed fish"}],"answer":"c","explanation":"The surge tank absorbs the pressure surges (water hammer) in the conduit caused by sudden changes in turbine flow.","marks":2,"source":{"kind":"past","set":16,"question":65,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q65 · 2 marks"},"topic":"ACiE0805"}]},{"name":"Transportation","questions":[{"id":"PAST-16-006","src":"PAST-16-006","text":"The right of way of a feeder road according to NRS 2070 is","options":[{"key":"a","text":"15"},{"key":"b","text":"20"},{"key":"c","text":"30"},{"key":"d","text":"50"}],"answer":"c","explanation":"Nepal Road Standard 2070 sets the right of way at 50 m for national highways and 30 m for feeder roads.","marks":1,"source":{"kind":"past","set":16,"question":6,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q6 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-16-012","src":"PAST-16-012","text":"The height of the headlight above the road surface is (taken as)","options":[{"key":"a","text":"0.3 m"},{"key":"b","text":"0.5 m"},{"key":"c","text":"0.75 m"},{"key":"d","text":"1 m"}],"answer":"c","explanation":"For headlight sight distance on valley curves, IRC assumes the headlight is 0.75 m above the road, with the beam inclined 1° upwards.","marks":1,"source":{"kind":"past","set":16,"question":12,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q12 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-16-023","src":"PAST-16-023","text":"Which of the following is not a factor that affects compaction?","options":[{"key":"a","text":"Method of compaction"},{"key":"b","text":"Texture of soil"},{"key":"c","text":"Addition of admixtures"},{"key":"d","text":"Water content"}],"answer":"b","explanation":"The standard factors are water content, compactive effort and method, soil type (gradation and plasticity) and admixtures. The key treats 'texture' as the item not listed among them.","marks":1,"source":{"kind":"past","set":16,"question":23,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q23 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-16-026","src":"PAST-16-026","text":"The distance from the pivot to the rear leg in the Benkelman beam test is","options":[{"key":"a","text":"0.25 m"},{"key":"b","text":"0.9 m"},{"key":"c","text":"1.66 m"},{"key":"d","text":"2.44 m"}],"answer":"c","explanation":"In the standard Benkelman beam, the probe arm is 2.44 m from the pivot to the tip, and the rear legs are 1.66 m behind the pivot.","marks":1,"source":{"kind":"past","set":16,"question":26,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q26 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-16-027","src":"PAST-16-027","text":"The vehicle distribution factor for a four lane single carriageway road is","options":[{"key":"a","text":"the design should be based on 40% of the commercial vehicles in both directions"},{"key":"b","text":"the design should be based on 75% of the commercial vehicles in both directions"},{"key":"c","text":"the design should be based on 60% of the commercial vehicles in both directions"},{"key":"d","text":"the design should be based on 45% of the commercial vehicles in both directions"}],"answer":"a","explanation":"For a four-lane single carriageway, 40% of the total commercial vehicles in both directions is taken as the design lane traffic. A two-lane road uses 75%.","marks":1,"source":{"kind":"past","set":16,"question":27,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q27 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-16-036","src":"PAST-16-036","text":"The standard loads used for calculation of CBR are","options":[{"key":"a","text":"1870 kg at 2.5 mm penetration and 2555 kg at 5.00 mm penetration"},{"key":"b","text":"1470 kg at 2.5 mm penetration and 2555 kg at 5.00 mm penetration"},{"key":"c","text":"1570 kg at 2.5 mm penetration and 2055 kg at 5.00 mm penetration"},{"key":"d","text":"1370 kg at 2.5 mm penetration and 2055 kg at 5.00 mm penetration"}],"answer":"d","explanation":"CBR compares the test load with the standard crushed-stone loads of 1370 kg at 2.5 mm and 2055 kg at 5.0 mm penetration.","marks":1,"source":{"kind":"past","set":16,"question":36,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q36 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-16-054","src":"PAST-16-054","text":"What is the unit of highway capacity?","options":[{"key":"a","text":"Veh/hr"},{"key":"b","text":"PCU/hr"},{"key":"c","text":"Veh/hr/section of road"},{"key":"d","text":"PCU/section of road"}],"answer":"b","explanation":"Capacity is the maximum hourly flow a road can carry, expressed in passenger car units per hour (per lane or per direction) to account for mixed traffic.","marks":1,"source":{"kind":"past","set":16,"question":54,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q54 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-16-061","src":"PAST-16-061","text":"The 15-minute traffic counts on cross roads 1 and 2 during the peak hour are observed as 178 and 142 vehicles per lane respectively, approaching the intersection in the direction of heavier traffic flow. If the amber times required are 3 and 2 seconds respectively for the two roads based on approach speeds, design the signal timings by the trial cycle method. Assume the average time headway as 2.5 seconds during the green phase.","options":[{"key":"a","text":"35 sec"},{"key":"b","text":"40 sec"},{"key":"c","text":"45 sec"},{"key":"d","text":"50 sec"}],"answer":"c","explanation":"Try \\(C = 45\\) s, giving \\(\\dfrac{900}{45} = 20\\) cycles in 15 min. The greens are \\[\\dfrac{178}{20} \\times 2.5 = 22.25\\ \\text{s}\\] \\[\\dfrac{142}{20} \\times 2.5 = 17.75\\ \\text{s}\\] Adding the ambers \\((3 + 2)\\) gives 45.0 s, which checks.","marks":2,"source":{"kind":"past","set":16,"question":61,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q61 · 2 marks"},"topic":"ACiE0904"},{"id":"PAST-16-067","src":"PAST-16-067","text":"As per NRS 2070, the maximum value of the coefficient of lateral friction is taken as","options":[{"key":"a","text":"0.35"},{"key":"b","text":"0.40"},{"key":"c","text":"0.1"},{"key":"d","text":"0.15"}],"answer":"d","explanation":"Horizontal curve design takes a lateral friction coefficient of 0.15. The longitudinal friction used for stopping sight distance is 0.35–0.40.","marks":2,"source":{"kind":"past","set":16,"question":67,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q67 · 2 marks"},"topic":"ACiE0902"},{"id":"PAST-16-068","src":"PAST-16-068","text":"Bitumen of grade 80/100 means","options":[{"key":"a","text":"its penetration value is 8 mm"},{"key":"b","text":"its penetration value is 10 mm"},{"key":"c","text":"its penetration value is 8 mm to 10 mm"},{"key":"d","text":"its penetration value is 8 mm to 10 cm"}],"answer":"c","explanation":"Penetration grade 80-100 means the standard needle penetrates 80-100 units of 0.1 mm, i.e. 8-10 mm, at \\(25^\\circ\\text{C}\\).","marks":2,"source":{"kind":"past","set":16,"question":68,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q68 · 2 marks"},"topic":"ACiE0903"},{"id":"PAST-16-070","src":"PAST-16-070","text":"In light compaction, the weight of the rammer recommended for the standard Proctor test is","options":[{"key":"a","text":"2.0 kg"},{"key":"b","text":"2.4 kg"},{"key":"c","text":"2.6 kg"},{"key":"d","text":"4.9 kg"}],"answer":"c","explanation":"The standard (light) Proctor test uses a 2.6 kg rammer falling 310 mm (IS 2720 Part 7). The heavy (modified) test uses a 4.9 kg rammer falling 450 mm.","marks":2,"source":{"kind":"past","set":16,"question":70,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q70 · 2 marks"},"topic":"ACiE0906"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-16-011","src":"PAST-16-011","text":"Nepal Engineering Council is a/an","options":[{"key":"a","text":"Government body"},{"key":"b","text":"Autonomous body"},{"key":"c","text":"Non-Government Organization"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"NEC is an autonomous statutory body with perpetual succession, established under the Nepal Engineering Council Act 2055.","marks":1,"source":{"kind":"past","set":16,"question":11,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q11 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-16-022","src":"PAST-16-022","text":"Which of the following statements is not correct regarding CPM and PERT?","options":[{"key":"a","text":"PERT is probabilistic in nature"},{"key":"b","text":"CPM is probabilistic in nature"},{"key":"c","text":"CPM and PERT use similar terminology but were developed independently"},{"key":"d","text":"all of these statements are correct"}],"answer":"b","explanation":"CPM is deterministic, with a single time estimate. PERT is probabilistic, with three time estimates, and the two were developed independently around 1957–58.","marks":1,"source":{"kind":"past","set":16,"question":22,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q22 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-16-040","src":"PAST-16-040","text":"The rules and regulations of the Nepal Engineering Council are approved by","options":[{"key":"a","text":"Government of Nepal"},{"key":"b","text":"Nepal Engineering Council"},{"key":"c","text":"Nepal Engineer's Association"},{"key":"d","text":"All of these"}],"answer":"a","explanation":"The Council frames its regulations under the NEC Act, but they take effect only with the approval of the Government of Nepal.","marks":1,"source":{"kind":"past","set":16,"question":40,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q40 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-16-049","src":"PAST-16-049","text":"How often is the regular inspection done for engineering institutions provided with permanent approval?","options":[{"key":"a","text":"Every year"},{"key":"b","text":"Every 18 months"},{"key":"c","text":"Twice a year"},{"key":"d","text":"Every two years"}],"answer":"d","explanation":"Per the source key, NEC carries out regular monitoring of permanently recognised engineering institutions every two years.","marks":1,"source":{"kind":"past","set":16,"question":49,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q49 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-16-051","src":"PAST-16-051","text":"The width of the standard A-series drawing paper, such as A4, A3, A2…, is","options":[{"key":"a","text":"\\(1/3\\) times the length of the paper"},{"key":"b","text":"\\(1/\\sqrt{2}\\) times the length of the paper"},{"key":"c","text":"\\(1/2\\) times the length of the paper"},{"key":"d","text":"\\(1/\\sqrt{3}\\) times the length of the paper"}],"answer":"b","explanation":"A-series sheets have sides in the ratio \\(1 : \\sqrt{2}\\) (for example 210 by 297 mm), so the width is \\(\\dfrac{1}{\\sqrt{2}}\\) times the length and halving a sheet keeps the same proportions.","marks":1,"source":{"kind":"past","set":16,"question":51,"marks":1,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q51 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-16-069","src":"PAST-16-069","text":"Which formula is used to calculate the earliest finish time (EF) of an activity during the forward pass in project scheduling?","options":[{"key":"a","text":"EF = ES + Duration − 1"},{"key":"b","text":"EF = LF − Duration + 1"},{"key":"c","text":"EF = ES + Duration"},{"key":"d","text":"EF = LF − Duration"}],"answer":"c","explanation":"In the forward pass \\[\\text{EF} = \\text{ES} + D\\] In the backward pass \\(\\text{LS} = \\text{LF} - D\\).","marks":2,"source":{"kind":"past","set":16,"question":69,"marks":2,"date":"2080 Chaitra 28","shift":"1st shift","reference":"Past Paper Set 16, Q69 · 2 marks"},"topic":"AALL1003"}]}]};
